/**
 * Signs release builds with an upload keystore when one is provided, and falls back to the debug
 * key otherwise, so `./gradlew assembleRelease` always produces an installable APK.
 *
 * The keystore is read from environment variables at build time (never committed):
 *   CHIONGBAH_UPLOAD_STORE_FILE      absolute path to the .jks / .keystore file
 *   CHIONGBAH_UPLOAD_STORE_PASSWORD
 *   CHIONGBAH_UPLOAD_KEY_ALIAS
 *   CHIONGBAH_UPLOAD_KEY_PASSWORD
 *
 * android/ is generated by `expo prebuild` (Continuous Native Generation), so this edit is applied
 * each time it is regenerated rather than by hand.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// chiongbah-release-signing';

const RELEASE_CONFIG = `
        ${MARKER}
        release {
            def uploadStore = System.getenv('CHIONGBAH_UPLOAD_STORE_FILE')
            if (uploadStore) {
                storeFile file(uploadStore)
                storePassword System.getenv('CHIONGBAH_UPLOAD_STORE_PASSWORD')
                keyAlias System.getenv('CHIONGBAH_UPLOAD_KEY_ALIAS')
                keyPassword System.getenv('CHIONGBAH_UPLOAD_KEY_PASSWORD')
            }
        }`;

function addReleaseSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  // 1. Add a release signing config next to the debug one.
  const debugConfig = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/;
  if (!debugConfig.test(gradle)) throw new Error('withReleaseSigning: signingConfigs.debug not found in app/build.gradle');
  gradle = gradle.replace(debugConfig, `$1${RELEASE_CONFIG}`);

  // 2. Point the release build type at it when a keystore was given.
  const releaseType = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
  if (!releaseType.test(gradle)) throw new Error('withReleaseSigning: release buildType signingConfig not found in app/build.gradle');
  return gradle.replace(
    releaseType,
    "$1signingConfig System.getenv('CHIONGBAH_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug",
  );
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') throw new Error('withReleaseSigning: expected a Groovy app/build.gradle');
    mod.modResults.contents = addReleaseSigning(mod.modResults.contents);
    return mod;
  });
};

module.exports.addReleaseSigning = addReleaseSigning;
